CREATE TABLE "Document" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"name" TEXT NOT NULL,"category" "DocumentCategory" NOT NULL,"visibility" "DocumentVisibility" NOT NULL DEFAULT 'ORGANIZATION',"mimeType" TEXT NOT NULL,"sizeBytes" BIGINT NOT NULL,"storageKey" TEXT NOT NULL,"checksum" TEXT,"entityType" TEXT,"entityId" TEXT,"expiresAt" TIMESTAMP(3),"currentVersion" INTEGER NOT NULL DEFAULT 1,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Document_pkey" PRIMARY KEY ("id"));
