CREATE TABLE "DocumentPermission" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"documentId" TEXT NOT NULL,"userId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DocumentPermission_pkey" PRIMARY KEY ("id"));
